import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import { useState, type ComponentProps, type CSSProperties } from "react";
import { cn } from "./lib/cn";
import "./split-bar.css";

export type SplitBarSegment = { id: string; label: string; value: number };

export type SplitBarProps = Omit<ComponentProps<"div">, "children"> & {
  /** Names the whole, e.g. "Revenue by plan". */
  label: string;
  segments: SplitBarSegment[];
  /** Formats a segment's own value for the readout. */
  format?: (value: number) => string;
};

const percent = (value: number, total: number) => (total ? Math.round((value / total) * 1000) / 10 : 0);

/**
 * One bar that is the whole, split into shares in the chart colours. Rest on a share, or focus its legend row, and it
 * widens to show its exact figures while the rest make room; switch shares off in the legend and the others spring
 * to fill the bar, with their percentages of what is left. Under reduced motion the widths change without the glide.
 */
export function SplitBar({ label, segments, format = (value) => value.toLocaleString("en-US"), className, ...props }: SplitBarProps) {
  const [hidden, setHidden] = useState<ReadonlySet<string>>(new Set());
  const [active, setActive] = useState<string | null>(null);
  const shown = segments.filter((segment) => !hidden.has(segment.id));
  const total = shown.reduce((sum, segment) => sum + segment.value, 0);
  const focus = shown.find((segment) => segment.id === active);

  const toggle = (id: string) =>
    setHidden((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else if (shown.length > 1) next.add(id); // the bar always keeps one share
      return next;
    });

  return (
    <div data-slot="split-bar" className={cn("grid gap-3", className)} {...props}>
      <div data-slot="sb-readout" aria-live="polite" className="flex min-h-6 items-baseline justify-between gap-3 text-sm">
        {focus ? (
          <>
            <span className="truncate font-medium">{focus.label}</span>
            <span className="shrink-0 tabular-nums">
              {format(focus.value)} <span className="text-muted-foreground">· {percent(focus.value, total)}%</span>
            </span>
          </>
        ) : (
          <>
            <span className="truncate text-muted-foreground">{label}</span>
            <span className="shrink-0 tabular-nums text-muted-foreground">{format(total)}</span>
          </>
        )}
      </div>
      <div data-slot="sb-bar" role="img" aria-label={`${label}: ${shown.map((segment) => `${segment.label} ${percent(segment.value, total)}%`).join(", ")}`} data-focused={focus ? "" : undefined}>
        {segments.map((segment, index) => {
          const off = hidden.has(segment.id);
          // The focused share takes an eighth of the bar on top of its own size, so even a sliver opens up to read.
          const grow = off ? 0 : segment.value + (segment.id === active ? total * 0.12 : 0);
          return (
            <span
              key={segment.id}
              data-slot="sb-segment"
              data-active={segment.id === active ? "" : undefined}
              data-off={off ? "" : undefined}
              style={{ flexGrow: grow, "--sb-color": `var(--chart-${(index % 6) + 1})` } as CSSProperties}
              onPointerEnter={() => setActive(segment.id)}
              onPointerLeave={() => setActive(null)}
            >
              <span data-slot="sb-share">{percent(segment.value, total)}%</span>
            </span>
          );
        })}
      </div>
      <ul data-slot="sb-legend" aria-label={`${label} shares`} className="flex flex-wrap gap-x-1 gap-y-1">
        {segments.map((segment, index) => {
          const off = hidden.has(segment.id);
          return (
            <li key={segment.id}>
              <button
                type="button"
                data-slot="sb-key"
                aria-pressed={!off}
                aria-disabled={!off && shown.length === 1 ? true : undefined}
                style={{ "--sb-color": `var(--chart-${(index % 6) + 1})` } as CSSProperties}
                onClick={() => toggle(segment.id)}
                onPointerEnter={() => !off && setActive(segment.id)}
                onPointerLeave={() => setActive(null)}
                onFocus={() => !off && setActive(segment.id)}
                onBlur={() => setActive(null)}
              >
                <span data-slot="sb-swatch" aria-hidden="true" />
                {segment.label}
                <span className="tabular-nums text-muted-foreground">{off ? "Off" : `${percent(segment.value, total)}%`}</span>
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/* split-bar.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Split bar: one whole; the focused share takes extra room and the rest make way. */
  [data-slot="split-bar"] [data-slot="sb-bar"] { display: flex; height: 36px; overflow: hidden; border-radius: var(--radius-control); }
  [data-slot="split-bar"] [data-slot="sb-segment"] { position: relative; display: flex; align-items: center; flex-basis: 0; min-width: 0; padding-inline: 8px; overflow: hidden; border-left: 2px solid var(--background); background: var(--sb-color); transition: flex-grow var(--duration-travel) var(--ease-settle), opacity var(--duration-normal) var(--ease-out), border-left-width var(--duration-travel) var(--ease-out); }
  [data-slot="split-bar"] [data-slot="sb-segment"]:first-child, [data-slot="split-bar"] [data-slot="sb-segment"][data-off] { border-left-width: 0; }
  [data-slot="split-bar"] [data-slot="sb-bar"][data-focused] [data-slot="sb-segment"]:not([data-active]) { opacity: 0.4; }
  [data-slot="split-bar"] [data-slot="sb-share"] { font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; color: var(--background); white-space: nowrap; opacity: 0; translate: 0 4px; transition: opacity var(--duration-normal) var(--ease-out), translate var(--duration-normal) var(--ease-out); }
  [data-slot="split-bar"] [data-slot="sb-segment"][data-active] [data-slot="sb-share"] { opacity: 1; translate: 0 0; transition-delay: 80ms; }
  [data-slot="split-bar"] [data-slot="sb-key"] { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px; border: 0; border-radius: var(--radius-control); background: none; color: var(--foreground); font-size: 13px; cursor: pointer; transition: background-color var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out); }
  [data-slot="split-bar"] [data-slot="sb-key"]:hover { background: var(--muted); }
  [data-slot="split-bar"] [data-slot="sb-key"][aria-pressed="false"] { color: var(--muted-foreground); }
  [data-slot="split-bar"] [data-slot="sb-key"][aria-disabled="true"] { cursor: default; }
  [data-slot="split-bar"] [data-slot="sb-key"]:focus-visible { outline: 2px solid var(--ring); outline-offset: 1px; }
  [data-slot="split-bar"] [data-slot="sb-swatch"] { width: 8px; height: 8px; border-radius: 2px; background: var(--sb-color); transition: background-color var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out); }
  [data-slot="split-bar"] [data-slot="sb-key"][aria-pressed="false"] [data-slot="sb-swatch"] { background: transparent; box-shadow: inset 0 0 0 1.5px var(--sb-color); }
  @media (pointer: coarse) { [data-slot="split-bar"] [data-slot="sb-key"] { height: 36px; } }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="split-bar"] [data-slot="sb-segment"], [data-slot="split-bar"] [data-slot="sb-share"] { transition: none; }
  }
}
